import React, { useState } from 'react';

const STAGES = [
  { name: 'Click', detail: 'Browser has a full URL and needs an IP address for the host.' },
  { name: 'DNS Lookup', detail: 'example.com is resolved to an IP address like 93.184.216.34.' },
  { name: 'HTTP Request', detail: 'Browser sends GET /products to that IP address.' },
  { name: 'Server Response', detail: 'Server sends back status 200 and the page HTML.' },
  { name: 'Render', detail: 'Browser fetches linked CSS/JS, runs them, and paints the page.' },
];

export default function RequestLifecycleDemo() {
  const [step, setStep] = useState(0);

  return (
    <div style={{ padding: 16, background: '#0d1117', color: '#e6edf3', fontFamily: 'sans-serif' }}>
      <h2 style={{ marginTop: 0, fontSize: 16, color: '#58a6ff' }}>example.com/products</h2>
      <div style={{ display: 'flex', gap: 8, marginBottom: 16 }}>
        {STAGES.map((s, i) => (
          <div
            key={s.name}
            style={{
              flex: 1,
              padding: '8px 4px',
              textAlign: 'center',
              fontSize: 12,
              borderRadius: 6,
              background: i <= step ? '#238636' : '#161b22',
              border: '1px solid #30363d',
            }}
          >
            {s.name}
          </div>
        ))}
      </div>
      <p style={{ color: '#8b949e', minHeight: 40 }}>{STAGES[step].detail}</p>
      <button
        onClick={() => setStep((s) => Math.min(s + 1, STAGES.length - 1))}
        disabled={step === STAGES.length - 1}
        style={{ background: '#238636', color: '#fff', border: 'none', padding: '8px 16px', borderRadius: 6, cursor: 'pointer' }}
      >
        {step === STAGES.length - 1 ? 'Page fully rendered' : 'Next stage →'}
      </button>
    </div>
  );
}

